package cn.luyin.player;

import java.util.*;

public final class AcousticAnalysisTest {
    private static int count;
    private static void check(boolean ok,String message){count++;if(!ok)throw new AssertionError(message);}
    private static void near(double actual,double expected,double error,String message){check(Math.abs(actual-expected)<=error,message+": "+actual+" vs "+expected);}
    private static double[] tone(int rate,double frequency,int length,double amplitude){double[] out=new double[length];for(int i=0;i<length;i++)out[i]=amplitude*Math.sin(2*Math.PI*frequency*i/rate);return out;}
    private static AcousticAnalyzer analyze(int rate,double frequency,double amplitude,boolean varying){AcousticAnalyzer a=new AcousticAnalyzer();for(int block=0;block<25;block++){short[] pcm=new short[rate/10];for(int i=0;i<pcm.length;i++){double t=block*.1+i/(double)rate;double phase=varying?2*Math.PI*frequency*t+6*Math.sin(2*Math.PI*2*t):2*Math.PI*frequency*t;pcm[i]=(short)Math.round(amplitude*Math.sin(phase)*32767);}a.accept(pcm,pcm.length,rate,(block+1)*.1,1,true);}return a;}
    public static void main(String[] args)throws Exception{
        for(double frequency:new double[]{41.2,110,220,440,880,1500}){double[] pcm=tone(14700,frequency,4096,.4);PitchDetector.Pitch p=PitchDetector.estimate(pcm,14700,-11);near(p.hz,frequency,Math.max(1,frequency*.012),"YIN pitch");check(p.confidence>.9,"periodicity confidence");}
        check(PitchDetector.estimate(new double[4096],14700,-120).hz==0,"silence has no pitch");check(PitchDetector.estimate(tone(14700,440,4096,1e-5),14700,-100).hz==0,"low-level signal rejected");check(PitchDetector.estimate(tone(14700,3000,4096,.4),14700,-11).hz==0,"out-of-range pitch not folded into range");
        double[] noise=new double[4096];Random random=new Random(18);for(int i=0;i<noise.length;i++)noise[i]=random.nextGaussian()*.1;check(PitchDetector.estimate(noise,14700,-20).hz==0,"white noise has no reliable pitch");
        check(PitchDetector.note(440).equals("A4"),"A4 note");check(PitchDetector.note(261.625565).equals("C4"),"C4 note");near(PitchDetector.cents(880,440),1200,1e-6,"cents per octave");near(PitchDetector.noteCents(440),0,1e-9,"reference tuning");
        double[] real=tone(1024,64,1024,1),imag=new double[1024];AudioFft.forward(real,imag);near(Math.hypot(real[64],imag[64]),512,1e-6,"FFT sine amplitude");
        AcousticAnalyzer a=analyze(44100,440,.5,false);SoundFrame f=a.latest();near(f.pitchHz,440,2,"streamed, decimated pitch");near(f.rmsDb,-9.03,.3,"RMS dBFS");check(f.sampleRate==14700,"anti-alias analysis sample rate");int max=0;for(int i=1;i<f.spectrumDb.length;i++)if(f.spectrumDb[i]>f.spectrumDb[max])max=i;near(max*f.sampleRate/(double)f.fftSize,440,5,"STFT peak");near(f.harmonicsDb[0],0,.001,"H1 reference");check(f.stability.pitchStdCents<2,"constant tone stable");check(f.stability.levelStdDb<.2,"constant amplitude stable");check(f.stability.voicedFraction>.95,"valid-pitch fraction");
        SoundFrame variable=analyze(44100,440,.5,true).latest();check(variable.stability.pitchStdCents>20,"frequency modulation raises pitch variation");
        SoundFrame amr=analyze(8000,220,.5,false).latest();near(amr.pitchHz,220,2,"8 kHz analysis");check(amr.sampleRate==8000,"AMR bandwidth correctly represented");
        AcousticAnalyzer harmonic=new AcousticAnalyzer();for(int block=0;block<20;block++){short[] pcm=new short[4410];for(int i=0;i<pcm.length;i++){double t=block*.1+i/44100.0;pcm[i]=(short)(32767*(.2*Math.sin(2*Math.PI*220*t)+.4*Math.sin(2*Math.PI*440*t)+.1*Math.sin(2*Math.PI*660*t)));}harmonic.accept(pcm,pcm.length,44100,(block+1)*.1,1,true);}f=harmonic.latest();near(f.pitchHz,220,2,"fundamental below stronger harmonic");near(f.harmonicsDb[1],6.02,2,"relative second harmonic");near(f.harmonicsDb[2],-6.02,2,"relative third harmonic");
        short[] silence=new short[4410];a.accept(silence,silence.length,44100,2.6,2,true);check(a.latest().segment==1,"new segment waits for complete window");for(int i=0;i<5;i++)a.accept(silence,silence.length,44100,2.7+i*.1,2,true);check(a.latest().pitchHz==0,"silence resets pitch");check(Double.isNaN(a.latest().stability.pitchStdCents),"no invented stability on silence");
        AcousticAnalyzer dc=new AcousticAnalyzer();short[] flat=new short[4410];Arrays.fill(flat,(short)12000);for(int i=0;i<8;i++)dc.accept(flat,flat.length,44100,(i+1)*.1,1,true);check(dc.latest().pitchHz==0,"DC is not a pitch");check(dc.latest().rmsDb<-90,"DC removed from AC RMS");
        byte[] adts=AdtsHeader.forFrame(300,44100,1);check((adts[0]&255)==255&&(adts[1]&255)==241,"ADTS sync");check(((adts[2]>>2)&15)==4,"44.1 kHz ADTS index");int length=((adts[3]&3)<<11)|((adts[4]&255)<<3)|((adts[5]&255)>>5);check(length==307,"ADTS frame length includes header");
        PianoSynth piano=new PianoSynth(48000);short[] out=new short[4800];piano.render(out,out.length);check(Arrays.equals(out,new short[out.length]),"unpressed piano silent");piano.noteOn(69);piano.render(out,out.length);long power=0;for(short v:out)power+=(long)v*v;check(power>0,"pressed key emits audio");near(PianoKeys.frequency(69),440,1e-9,"piano A4 frequency");piano.noteOff(69);for(int i=0;i<20;i++)piano.render(out,out.length);check(piano.voiceCount()==0,"released voice decays and is removed");piano.noteOn(60);piano.noteOn(64);piano.noteOn(67);piano.render(out,out.length);check(piano.voiceCount()==3,"polyphony");piano.allOff();piano.render(out,out.length);check(Arrays.equals(out,new short[out.length]),"all notes off prevents stuck notes");
        check(PianoKeys.hit(2,200,1400,300,60)==60,"white C key");check(PianoKeys.hit(100,30,1400,300,60)==61,"black C sharp priority");check(PianoKeys.hit(300,30,1400,300,60)==65,"no black key between E and F");check(PianoKeys.hit(-1,0,1400,300,60)==-1,"outside keyboard ignored");
        LiveAnalysis live=new LiveAnalysis();live.newSession();short[] stream=new short[44100];for(int i=0;i<stream.length;i++)stream[i]=(short)(14000*Math.sin(2*Math.PI*440*i/44100));live.submit(stream,stream.length,44100);Arrays.fill(stream,(short)0);long deadline=System.nanoTime()+5_000_000_000L;while(live.snapshot().latest()==null&&System.nanoTime()<deadline)Thread.sleep(10);check(live.snapshot().latest()!=null,"asynchronous PCM reaches analysis");near(live.snapshot().latest().pitchHz,440,2,"submission copies reusable microphone buffer");long oldSegment=live.snapshot().segment;live.boundary();check(live.snapshot().segment!=oldSegment&&live.snapshot().latest()!=null,"pause freezes history and starts new segment");live.newSession();check(live.snapshot().frames.isEmpty(),"new session clears analysis history");live.configure(false,false);live.submit(stream,stream.length,44100);check(live.snapshot().frames.isEmpty(),"disabled analysis leaves recording input untouched");
        near(PitchAxis.frequency(69),440,1e-9,"scientific A4 reference");near(PitchAxis.frequency(72),523.251131,.00001,"scientific C5");near(PitchAxis.frequency(60),261.625565,.00001,"middle C is C4");near(PitchAxis.position(40),1,1e-9,"axis lower bound");near(PitchAxis.position(1800),0,1e-9,"axis upper bound");near(PitchAxis.position(440)-PitchAxis.position(PitchAxis.frequency(70)),PitchAxis.position(PitchAxis.frequency(70))-PitchAxis.position(PitchAxis.frequency(71)),1e-9,"equal semitone spacing");check(Double.isNaN(PitchAxis.position(0))&&Double.isNaN(PitchAxis.position(2500)),"invalid or out-of-range pitch not plotted");boolean a4=false,c5=false;for(PitchAxis.Tick tick:PitchAxis.ticks(true)){if(tick.label.equals("A4")){a4=true;near(tick.hz,440,1e-9,"A4 tick at actual measured frequency");}if(tick.label.equals("C5")){c5=true;near(tick.hz,523.251131,.00001,"C5 tick at actual measured frequency");}}check(a4&&c5,"scientific labels include A4 and C5");double detuned=440*Math.pow(2,20/1200.0);check(PitchAxis.position(detuned)<PitchAxis.position(440)&&PitchAxis.position(detuned)>PitchAxis.position(PitchAxis.frequency(70)),"detuning remains continuous rather than snapped to note");check(PitchAxis.ticks(false).get(0).label.equals("100"),"Hz axis retained");
        System.out.println("Passed "+count+" acoustic analysis, codec-header and piano-synthesis checks.");
    }
}
